refs.w2_teilezaehler:
// Programm (SCL)
"Flanke_B1"(CLK := "Ind_Metall");
IF "Flanke_B1".Q THEN
  "Teile_Anzahl" := "Teile_Anzahl" + 1;
END_IF;
IF "HMI_Reset" THEN
  "Teile_Anzahl" := 0;
END_IF;

refs.w3_materialsortierung:
// Programm (SCL)
IF "Ind_Metall" THEN
  "Ist_Metall" := TRUE;
END_IF;
"Auswerfer" := "LS_Band" AND "Ist_Metall";
IF "Zyl_Vorne" THEN
  "Ist_Metall" := FALSE;
END_IF;

refs.w3_endlagen_ueberwachung:
// Programm (SCL)
"Auswerfer" := "Befehl_Auswerfen" AND NOT "Lampe_Rot";
"T_Vorne"(IN := "Auswerfer" AND NOT "Zyl_Vorne", PT := T#2S);
"T_Hinten"(IN := NOT "Auswerfer" AND NOT "Zyl_Hinten", PT := T#2S);
IF "T_Vorne".Q OR "T_Hinten".Q THEN
  "Lampe_Rot" := TRUE;
END_IF;
IF "Quittieren" THEN
  "Lampe_Rot" := FALSE;
END_IF;
